struct X1Options { std::filesystem::path output; std::string productionEvidence = "NOT_RECORDED"; std::string benchmarkEvidence = "NOT_RECORDED"; };
struct Distribution {
    std::uint64_t n = 0U, state = 0x51f15e5dULL;
    double sum = 0.0, maximum = 0.0;
    std::vector<double> reservoir;
    void add(double value) {
        if (!std::isfinite(value)) return;
        ++n; sum += value; maximum = std::max(maximum, value);
        if (reservoir.size() < 8192U) reservoir.push_back(value);
        else { state ^= state << 13U; state ^= state >> 7U; state ^= state << 17U;
            const std::uint64_t slot = state % n;
            if (slot < reservoir.size()) reservoir[static_cast<size_t>(slot)] = value; }
    }
    double mean() const { return n ? sum / static_cast<double>(n) : 0.0; }
    double q(double fraction) const {
        if (reservoir.empty()) return 0.0;
        auto copy = reservoir; const size_t index = static_cast<size_t>(std::floor(
            std::clamp(fraction, 0.0, 1.0) * static_cast<double>(copy.size() - 1U)));
        std::nth_element(copy.begin(), copy.begin() + static_cast<std::ptrdiff_t>(index), copy.end()); return copy[index];
    }
};
struct Feature { double innovation = 0.0, disagreement = 0.0, curvature = 0.0, age = 0.0, travel = 0.0; };
