// The exact X0 generator's ordering is retained, but only a requested split is
// materialized.  Non-requested rows, particularly HOLDOUT, are never formed or scored.
struct SplitRoute {
    std::uint32_t seed = 0U;
    std::size_t scenarios = 0U;
};

// X0 split identity is a closed domain.  There is deliberately no fallback:
// an invalid value stops before any corpus row can be generated.
SplitRoute splitRouteFor(Split wanted) {
    switch (wanted) {
    case Split::Development: return {0x240A1001U, 1800U};
    case Split::Validation: return {0x240A1002U, 600U};
    case Split::Holdout: return {0x240A1003U, 600U};
    }
    throw std::invalid_argument("unknown X0 corpus split");
}

std::vector<Scenario> corpusFor(Split wanted) {
    const SplitRoute route = splitRouteFor(wanted);
    std::vector<Scenario> result; result.reserve(route.scenarios);
    const std::array<std::string, 5> sensors{"CLEAN", "QUANTIZED", "JITTERY", "SPIKY_DRIFT", "LOW_RATE_HOLD"};
    const std::array<std::string, 22> structured{"SLOW_BALLISTIC", "MEDIUM_BALLISTIC", "FAST_BALLISTIC", "VERY_FAST_BALLISTIC", "CONSTANT_VELOCITY", "ACCELERATION_RAMP", "DECELERATION", "ABRUPT_STOP", "BRAKE_CONTINUE", "BRAKE_REVERSE", "CENTER_CROSSING_REVERSAL", "POSITIVE_SIDE_REVERSAL", "NEGATIVE_SIDE_REVERSAL", "REPEATED_REVERSAL", "OSCILLATION", "HIGH_JERK", "ENDPOINT_APPROACH", "ENDPOINT_RECOIL", "STATIONARY_JITTER", "MICRO_CORRECTION", "CADENCE_JITTER", "SAMPLE_HOLD_STRESS"};
    std::uint32_t global = 0U;
    const auto add = [&](int count, const std::string &family, const std::string &envelope, const std::string &tag) {
        for (int local = 0; local < count; ++local, ++global) {
            const int ordinal = local % 10; const Split split = ordinal < 6 ? Split::Development : ordinal < 8 ? Split::Validation : Split::Holdout;
            if (split != wanted) continue;
            const std::string motion = envelope == "STRUCTURED" ? structured[static_cast<size_t>(local) % structured.size()] : envelope == "TORTURE_BEYOND_HUMAN" ? "TORTURE_" + std::to_string(local % 5) : family;
            const std::string sensor = sensors[static_cast<size_t>(global) % sensors.size()]; std::string tags = tag;
            if (motion.find("BALLISTIC") != std::string::npos || motion == "CONSTANT_VELOCITY") tags += "|VELOCITY_STRESS";
            if (motion == "ACCELERATION_RAMP" || motion == "DECELERATION") tags += "|ACCELERATION_STRESS";
            if (motion.find("REVERSAL") != std::string::npos || motion == "OSCILLATION") tags += "|REVERSAL_STRESS";
            if (motion == "HIGH_JERK") tags += "|JERK_STRESS";
            if (motion == "ABRUPT_STOP" || motion.find("BRAKE") != std::string::npos) tags += "|STOP_STRESS";
            if (sensor == "JITTERY" || sensor == "SPIKY_DRIFT") tags += "|NOISE_STRESS";
            if (sensor == "LOW_RATE_HOLD" || motion == "CADENCE_JITTER") tags += "|CADENCE_STRESS";
            const double amplitude = motion == "SLOW_BALLISTIC" ? .20 : motion == "MEDIUM_BALLISTIC" ? .42 : motion == "FAST_BALLISTIC" ? .70 : motion == "VERY_FAST_BALLISTIC" ? .92 : .65;
            result.push_back({global, route.seed ^ (global * 0x9e3779b9U), wanted, "X0-" + std::to_string(global + 1U), family, motion, sensor, envelope, tags, sensor == "LOW_RATE_HOLD" ? "LOW_RATE_HOLD_BOUNDED" : motion == "CADENCE_JITTER" ? "VARIABLE_CADENCE_BOUNDED" : "R0.65_BOUNDED_NOMINAL", motion == "VERY_FAST_BALLISTIC" ? .38 : .80, amplitude, .05});
        }
    };
    add(350, "PRECISION_REALISTIC", "HUMAN_REPRESENTATIVE", "HUMAN_REPRESENTATIVE"); add(500, "COMBAT_REALISTIC", "HUMAN_REPRESENTATIVE", "HUMAN_REPRESENTATIVE"); add(250, "COMBAT_HUMAN_EXTREME", "HUMAN_REPRESENTATIVE", "HUMAN_REPRESENTATIVE"); add(300, "FIXED_WING_REALISTIC", "HUMAN_REPRESENTATIVE", "HUMAN_REPRESENTATIVE"); add(300, "SPACE_SIM_REALISTIC", "HUMAN_REPRESENTATIVE", "HUMAN_REPRESENTATIVE");
    add(400, "STRUCTURED", "STRUCTURED", "STRUCTURED_CONTROL"); add(250, "STRUCTURED", "STRUCTURED", "STRUCTURED_CONTROL"); add(200, "STRUCTURED", "STRUCTURED", "STRUCTURED_CONTROL"); add(150, "STRUCTURED", "STRUCTURED", "STRUCTURED_CONTROL"); add(150, "STRUCTURED", "STRUCTURED", "STRUCTURED_CONTROL"); add(150, "TORTURE_BEYOND_HUMAN", "TORTURE_BEYOND_HUMAN", "TORTURE_BEYOND_HUMAN");
    return result;
}

class FixedQ5 final {
public:
    void accept(const SourceReport &report) { if (count < points.size()) points[count++] = {report.time, report.value}; else { for (size_t i=1;i<points.size();++i) points[i-1]=points[i]; points.back()={report.time,report.value}; } if (count == points.size()) solve(); }
    double predict(double time) const { if (!count) return 0.0; if (!valid) return points[count-1U].second; const double d=time-points[count-1U].first; return coefficients[0]+coefficients[1]*d+coefficients[2]*d*d; }
private:
    void solve() { const double newest=points.back().first; double a[3][4]{}; for (const auto &point:points) { const double t=point.first-newest; const std::array<double,3> b{1,t,t*t}; for(int r=0;r<3;++r){a[r][3]+=b[r]*point.second;for(int c=0;c<3;++c)a[r][c]+=b[r]*b[c];} } for(int p=0;p<3;++p){int best=p;for(int r=p+1;r<3;++r)if(std::abs(a[r][p])>std::abs(a[best][p]))best=r;if(std::abs(a[best][p])<1e-12){valid=false;return;}for(int c=p;c<4;++c)std::swap(a[p][c],a[best][c]);const double d=a[p][p];for(int c=p;c<4;++c)a[p][c]/=d;for(int r=0;r<3;++r)if(r!=p){const double f=a[r][p];for(int c=p;c<4;++c)a[r][c]-=f*a[p][c];}} coefficients={a[0][3],a[1][3],a[2][3]};valid=true; }
    std::array<std::pair<double,double>,5> points{}; std::array<double,3> coefficients{}; size_t count=0U; bool valid=false;
};
double velocityOf(const FixedQ3 &q, double at) { constexpr double e=.00025; return (q.predict(at+e)-q.predict(at-e))/(2.0*e); }
double accelerationOf(const FixedQ3 &q, double at) { constexpr double e=.0005; return (q.predict(at+e)-2.0*q.predict(at)+q.predict(at-e))/(e*e); }
struct FeatureState {
    FixedQ3 q3; FixedQ5 q5; double innovation=0.0, jerk=0.0, travel=.003, period=kSourceMedianSeconds, cadence=.0, priorValue=0.0, priorAcceleration=0.0, lastReport=0.0, direction=0.0; int reports=0, quiet=0, stop=0, reversalGuard=0;
    void accept(const SourceReport &r) {
        const double priorPrediction = reports >= 3 ? q3.predict(r.time) : r.value; innovation = r.value-priorPrediction;
        const double priorA = reports >= 3 ? accelerationOf(q3,r.time) : 0.0; const double delta = reports ? r.value-priorValue : 0.0;
        if (reports && std::abs(delta) < .0015) ++quiet; else quiet=0; if (reports && std::abs(delta) < .001 && std::abs(direction) > 0.0) ++stop; else stop=0;
        const double newDirection = std::abs(delta) > .0015 ? (delta > 0.0 ? 1.0 : -1.0) : direction;
        if (direction != 0.0 && newDirection != 0.0 && newDirection != direction) reversalGuard=2;
        if (std::abs(delta) > .0015) direction=newDirection;
        if (r.interval > 0.0) { const double priorPeriod=period; period=.85*period+.15*r.interval; cadence=.85*cadence+.15*std::abs(r.interval-priorPeriod); }
        travel=.85*travel+.15*std::abs(delta); q3.accept(r); q5.accept(r); const double newA=reports >= 2 ? accelerationOf(q3,r.time) : 0.0;
        jerk=r.interval > .0005 ? std::abs(newA-priorA)/r.interval : 0.0; priorAcceleration=newA; priorValue=r.value; lastReport=r.time; ++reports;
    }
    Feature features(double mapperTime, double horizon) const {
        const double q3q5=std::abs(q3.predict(mapperTime+horizon)-q5.predict(mapperTime+horizon));
        return {std::abs(innovation), q3q5, jerk, std::max(0.0,mapperTime-lastReport)/std::max(.003,period)+cadence/std::max(.003,period), travel};
    }
    bool veto(double lead) const { return (reversalGuard > 0 && lead*direction < 0.0) || quiet >= 2 || stop >= 2; }
    void mapperAdvance() { if (reversalGuard > 0) --reversalGuard; }
};
double scaled(double value, double scale) { return std::clamp(value / std::max(1e-8,scale), 0.0, 4.0); }
double risk(const RiskSpec &spec, const Feature &f, const Scales &s) {
    double value=0.0; if(spec.innovation)value=std::max(value,scaled(f.innovation,s.innovation)); if(spec.disagreement)value=std::max(value,scaled(f.disagreement,s.disagreement)); if(spec.curvature)value=std::max(value,scaled(f.curvature,s.curvature)); if(spec.age)value=std::max(value,scaled(f.age,s.age)); return std::min(1.0,value);
}
size_t riskBin(double value) { return std::min<size_t>(4U, static_cast<size_t>(std::floor(std::clamp(value,0.0,.999999)*5.0))); }
double qualityBudget(BudgetId id, const Feature &f) { if(id==BudgetId::Absolute)return .040; if(id==BudgetId::Travel)return std::min(.060,.020+.25*std::min(.16,f.travel)); return .042; }
size_t chooseHorizon(const RiskSpec &spec, const Calibration &calibration, const FeatureState &state, double mapperTime) {
    const auto &bounds=calibration.p95[static_cast<size_t>(spec.id)]; size_t chosen=0U;
    for(size_t i=0;i<kX1HorizonsMs.size();++i){const Feature f=state.features(mapperTime,kX1HorizonsMs[i]/1000.0); const size_t bin=riskBin(risk(spec,f,calibration.scales)); if(bounds[i][bin]<=qualityBudget(spec.budget,f))chosen=i;}
    return chosen;
}
bool isStructured(const Scenario &s) { return s.envelope=="STRUCTURED"; }
void addGroup(Group &g, double raw, double bounded, double horizon, const Feature &f, double oracle) { ++g.n;g.raw.add(std::abs(raw));g.bounded.add(std::abs(bounded));g.horizon.add(horizon);g.innovation.add(f.innovation);g.disagreement.add(f.disagreement);g.curvature.add(f.curvature);g.age.add(f.age);g.oracle.add(oracle); }
void addFeatureAudit(Result &r, const Feature &f, double error, const Scales &s) { const std::array<double,4> v{f.innovation,f.disagreement,f.curvature,f.age}; const std::array<double,4> scale{s.innovation,s.disagreement,s.curvature,s.age}; for(size_t i=0;i<v.size();++i){r.correlations[i].add(v[i],std::abs(error));auto &b=r.bins[i][riskBin(scaled(v[i],scale[i])/4.0)];++b.n;b.error.add(std::abs(error));if(v[i]<=scale[i]&&std::abs(error)>.05)++b.falseSafe;if(v[i]>scale[i]&&std::abs(error)<=.05)++b.falseConservative;} }

Scales deriveScales(const std::vector<Scenario> &items) {
    std::array<Distribution,4> values;
    for(const auto &s:items){const Timeline t=buildTimeline(s);FeatureState state;size_t cursor=0U;for(const auto &sample:t.mapper){while(cursor<t.reports.size()&&t.reports[cursor].time<=sample.time+1e-9)state.accept(t.reports[cursor++]);if(sample.time<s.analysisStart)continue;const Feature f=state.features(sample.time,.008);values[0].add(f.innovation);values[1].add(f.disagreement);values[2].add(f.curvature);values[3].add(f.age);state.mapperAdvance();}}
    return {std::max(.001,values[0].q(.90)),std::max(.001,values[1].q(.90)),std::max(.01,values[2].q(.90)),std::max(.05,values[3].q(.90))};
}
Calibration calibrate(const std::vector<Scenario> &items, const Scales &scales) {
    Calibration result; result.scales=scales;
    for(const auto &s:items){const Timeline t=buildTimeline(s);FeatureState state;size_t cursor=0U;for(const auto &sample:t.mapper){while(cursor<t.reports.size()&&t.reports[cursor].time<=sample.time+1e-9)state.accept(t.reports[cursor++]);if(sample.time<s.analysisStart){state.mapperAdvance();continue;}for(size_t h=0;h<kX1HorizonsMs.size();++h){const double seconds=kX1HorizonsMs[h]/1000.0;if(sample.time+seconds>s.duration+1e-9)continue;const double error=state.q3.predict(sample.time+seconds)-latentAt(s,sample.time+seconds);const Feature f=state.features(sample.time,seconds);for(const auto &spec:kRiskSpecs)result.bounds[static_cast<size_t>(spec.id)].errors[h][riskBin(risk(spec,f,scales))].add(std::abs(error));}state.mapperAdvance();}}
    for(size_t candidate=0;candidate<kRiskSpecs.size();++candidate)for(size_t h=0;h<kX1HorizonsMs.size();++h)for(size_t bin=0;bin<5;++bin)result.p95[candidate][h][bin]=result.bounds[candidate].errors[h][bin].q(.95);
    return result;
}
struct FixedResult { std::map<std::string, std::array<Distribution,3>> rows; };
FixedResult scoreFixed(const std::vector<Scenario> &items) {
    FixedResult result;
    for(const auto &s:items){const Timeline t=buildTimeline(s);FeatureState state; hotas::AdaptiveResponseProcessor v23;size_t cursor=0U;const auto origin=std::chrono::steady_clock::time_point{};for(const auto &sample:t.mapper){while(cursor<t.reports.size()&&t.reports[cursor].time<=sample.time+1e-9)state.accept(t.reports[cursor++]);const auto timestamp=origin+std::chrono::microseconds(static_cast<long long>(std::llround(sample.time*1e6)));const auto tele=v23.process(static_cast<float>(sample.held),v23Config(),timestamp);if(sample.time>=s.analysisStart)for(const double ms:kX1HorizonsMs){const double h=ms/1000.0;if(sample.time+h>s.duration+1e-9)continue;auto &d=result.rows[s.family+"|"+number(ms,3)];const double truth=latentAt(s,sample.time+h);d[0].add(std::abs(state.q3.predict(sample.time+h)-truth));d[1].add(std::abs(state.q5.predict(sample.time+h)-truth));d[2].add(std::abs(sample.held+tele.velocity*h-truth));}state.mapperAdvance();}}
    return result;
}
Result runPolicy(const std::vector<Scenario> &items, const RiskSpec &spec, const Calibration &calibration) {
    Result result;
    for(const auto &s:items){const Timeline t=buildTimeline(s);FeatureState state;size_t cursor=0U;for(const auto &sample:t.mapper){while(cursor<t.reports.size()&&t.reports[cursor].time<=sample.time+1e-9)state.accept(t.reports[cursor++]);if(sample.time<s.analysisStart){state.mapperAdvance();continue;}const size_t index=chooseHorizon(spec,calibration,state,sample.time);const double h=kX1HorizonsMs[index]/1000.0;if(sample.time+h>s.duration+1e-9){state.mapperAdvance();continue;}const Feature f=state.features(sample.time,h);const double raw=state.q3.predict(sample.time+h);double lead=raw-sample.held;const bool veto=state.veto(lead);if(veto)lead=0.0;const double bounded=clampPosition(sample.held+std::clamp(lead,-.18,.18));const double truth=latentAt(s,sample.time+h);if(!std::isfinite(bounded))++result.safety.finiteFailures;if(bounded<-1.000001||bounded>1.000001)++result.safety.illegalBounds;if(veto&&std::abs(bounded-sample.held)>.00001){if(state.quiet>=2)++result.safety.quietResidual;else if(state.stop>=2)++result.safety.stopResidual;else ++result.safety.staleDirection;}double oracle=0.0;for(size_t j=0;j<kX1HorizonsMs.size();++j){const double oh=kX1HorizonsMs[j]/1000.0;if(sample.time+oh<=s.duration&&std::abs(state.q3.predict(sample.time+oh)-latentAt(s,sample.time+oh))<=qualityBudget(spec.budget,state.features(sample.time,oh)))oracle=kX1HorizonsMs[j];}auto &family=result.family[s.family];auto &sensor=result.sensor[s.sensor];auto &structured=result.structured[isStructured(s)?s.motion:"HUMAN_OR_TORTURE"];addGroup(family,raw-truth,bounded-truth,kX1HorizonsMs[index],f,oracle);addGroup(sensor,raw-truth,bounded-truth,kX1HorizonsMs[index],f,oracle);addGroup(structured,raw-truth,bounded-truth,kX1HorizonsMs[index],f,oracle);result.allRaw.add(std::abs(raw-truth));result.allBounded.add(std::abs(bounded-truth));result.allHorizon.add(kX1HorizonsMs[index]);addFeatureAudit(result,f,raw-truth,calibration.scales);++result.samples;state.mapperAdvance();}}
    return result;
}
std::string csvGroups(const std::map<std::string,Group> &groups, std::string_view dimension, std::string_view stream) { std::ostringstream out;out<<"stream,"<<dimension<<",samples,raw_mae,bounded_mae,raw_p95,bounded_p95,raw_p99,bounded_p99,median_horizon_ms,p10_horizon_ms,p25_horizon_ms,p75_horizon_ms,p90_horizon_ms,median_oracle_horizon_ms\n";for(const auto &[name,g]:groups)out<<stream<<','<<csv(name)<<','<<g.n<<','<<number(g.raw.mean())<<','<<number(g.bounded.mean())<<','<<number(g.raw.q(.95))<<','<<number(g.bounded.q(.95))<<','<<number(g.raw.q(.99))<<','<<number(g.bounded.q(.99))<<','<<number(g.horizon.q(.50))<<','<<number(g.horizon.q(.10))<<','<<number(g.horizon.q(.25))<<','<<number(g.horizon.q(.75))<<','<<number(g.horizon.q(.90))<<','<<number(g.oracle.q(.50))<<'\n';return out.str(); }
