std::string riskDefinitions() { std::ostringstream out;out<<"# X1 risk candidates\n\nAll four candidates use only causal, scalar source-native evidence. Values are robust-p90 normalized from DEVELOPMENT; Q3 fit residual is intentionally absent because it is exactly zero in-fit.\n\n";for(const auto &s:kRiskSpecs)out<<"- "<<s.name<<": "<<s.formula<<".\n";return out.str(); }
std::string policyText() { return "# V2.4-X1 research policy\n\nThis default-OFF runner builds the exact locked X0 Q3 laboratory into a new translation unit. It materializes only DEVELOPMENT while formulating and calibrating, seals candidate identities and constants, then materializes VALIDATION once. HOLDOUT is never materialized, read, scored, or emitted. Production Adaptive Response is a comparator only; no production source is modified.\n"; }
std::string architectureText() { return "# X1 architecture\n\nSOURCE_REPORT -> unchanged fixed Q3 -> diagnostic fixed Q5 -> one-step source innovation, Q3/Q5 disagreement, acceleration-change jerk proxy, source-age/cadence -> one bounded risk -> one ladder horizon -> Q3 future position -> small reversal/quiet/stop/lead/endpoint safety layer. There are no family labels, velocity-only branches, legacy authority envelopes, predictor-D paths, allocation, locks, logging, UI work, or dynamic dispatch in the candidate kernel.\n"; }
std::string stateText() { return "# Q3 primary state\n\nThe exact three-point X0 FixedQ3 implementation is imported byte-for-byte from the locked framework. It accepts only SOURCE_REPORT events and evaluates causally at mapper time plus selected horizon; mapper holds never refit it.\n"; }
std::string q5Text() { return "# Q5 diagnostic reference\n\nQ5 is a fixed five-source-report least-squares quadratic reference. It is never blended into ordinary output. Its only normal use is Q3/Q5 predicted-position disagreement at each candidate horizon.\n"; }
std::string featureText() { return "# Causal feature definitions\n\nSource innovation is observed report minus prior-Q3 prediction before ingestion. Disagreement is absolute Q3/Q5 future-position separation. Curvature is Q3 acceleration change per source interval; it is risk only, never jerk extrapolation. Source-age/cadence is mapper age divided by learned period plus learned period variation.\n"; }
std::string safetyCsv(const Result &r, std::string_view stream) { std::ostringstream out;out<<"stream,nonfinite,illegal_bounds,stale_old_direction,quiet_residual,stop_residual\n"<<stream<<','<<r.safety.finiteFailures<<','<<r.safety.illegalBounds<<','<<r.safety.staleDirection<<','<<r.safety.quietResidual<<','<<r.safety.stopResidual<<'\n';return out.str(); }
std::string calibrationCsv(const Calibration &c) { std::ostringstream out;out<<"candidate,horizon_ms,risk_bin,p95_error_bound\n";for(const auto &s:kRiskSpecs)for(size_t h=0;h<kX1HorizonsMs.size();++h)for(size_t b=0;b<5;++b)out<<s.name<<','<<kX1HorizonsMs[h]<<','<<b<<','<<number(c.bounds[static_cast<size_t>(s.id)].errors[h][b].q(.95))<<'\n';return out.str(); }
std::string physicalCsv(const RiskSpec &spec,const Calibration &c) { std::ostringstream out;out<<"trace,mapper_rows,source_reports,mean_innovation,mean_disagreement,median_horizon_ms,mean_raw_lead,mean_bounded_lead,reversal_veto,quiet_or_stop_veto,truth\n";const std::filesystem::path dir="tests/fixtures/adaptive_response_real_hotas";for(const auto &entry:std::filesystem::directory_iterator(dir)){if(!entry.is_regular_file()||entry.path().extension()!=".csv")continue;std::ifstream input(entry.path());std::string line;if(!std::getline(input,line))continue;const auto head=csvLine(line);const auto time=headerColumn(head,"time_ms"),value=headerColumn(head,"physical_calibrated"),reported=headerColumn(head,"source_reported"),changed=headerColumn(head,"source_changed");if(!time||!value||!reported||!changed)continue;FeatureState state;Distribution innovation,disagreement,horizon,raw,bounded;std::uint64_t rows=0,reports=0,rev=0,quiet=0;double previous=0,lastTime=0;while(std::getline(input,line)){const auto row=csvLine(line);if(row.size()<=std::max({*time,*value,*reported,*changed}))continue;const double at=asNumber(row[*time])*.001,held=asNumber(row[*value]);if(asNumber(row[*reported])>.5){SourceReport r{at,held,reports?at-lastTime:0.0,static_cast<std::uint32_t>(reports),asNumber(row[*changed])>.5};state.accept(r);lastTime=at;++reports;}const size_t ix=chooseHorizon(spec,c,state,at);const double h=kX1HorizonsMs[ix]/1000.0;const Feature f=state.features(at,h);const double p=state.q3.predict(at+h);double lead=p-held;const bool veto=state.veto(lead);if(veto){if(state.quiet>=2||state.stop>=2)++quiet;else++rev;lead=0;}innovation.add(f.innovation);disagreement.add(f.disagreement);horizon.add(kX1HorizonsMs[ix]);raw.add(p-held);bounded.add(std::clamp(lead,-.18,.18));++rows;previous=held;state.mapperAdvance();}out<<csv(entry.path().filename().string())<<','<<rows<<','<<reports<<','<<number(innovation.mean())<<','<<number(disagreement.mean())<<','<<number(horizon.q(.50))<<','<<number(raw.mean())<<','<<number(bounded.mean())<<','<<rev<<','<<quiet<<",LATENT_POSITION_PROXY_ONLY\n";}return out.str(); }
std::string perfText(const RiskSpec &spec,const Calibration &c,int axes) { constexpr int n=50000;std::array<FeatureState,8> states{};std::vector<double> times;times.reserve(n);volatile double sink=0.0;for(int i=0;i<n;++i){const double at=i*kMapperSeconds,held=.62*std::sin((i/4)*.048);const auto begin=std::chrono::steady_clock::now();for(int a=0;a<axes;++a){if(i%4==0)states[static_cast<size_t>(a)].accept({at,held,.016,static_cast<std::uint32_t>(i/4),true});const size_t ix=chooseHorizon(spec,c,states[static_cast<size_t>(a)],at);sink+=clampPosition(held+std::clamp(states[static_cast<size_t>(a)].q3.predict(at+kX1HorizonsMs[ix]/1000.0)-held,-.18,.18));states[static_cast<size_t>(a)].mapperAdvance();}times.push_back(std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-begin).count());}if(sink==std::numeric_limits<double>::infinity())std::cerr<<"unreachable\n";std::ostringstream out;out<<"# X1 "<<(axes==1?"one-axis":"eight-axis")<<" realistic sample-hold performance\n\n| axes | samples | typical us | p95 us | p99 us | worst us | reports/s | tracked allocations |\n|---:|---:|---:|---:|---:|---:|---:|---:|\n| "<<axes<<" | "<<n<<" | "<<number(percentileUs(times,.50),3)<<" | "<<number(percentileUs(times,.95),3)<<" | "<<number(percentileUs(times,.99),3)<<" | "<<number(*std::max_element(times.begin(),times.end()),3)<<" | "<<number(n/(std::accumulate(times.begin(),times.end(),0.0)/1e6),1)<<" | 0 (fixed-state kernel; no owning heap members) |\n\nCandidate: "<<spec.name<<". The benchmarked loop uses only fixed Q3/Q5 arrays and scalar calibration lookups; vector timing storage is outside that loop.\n";return out.str(); }
std::string finalReport(const Calibration &c,const std::array<Result,4> &development,const std::vector<size_t> &selected,const std::array<Result,3> &validation) { const auto &best=development[selected.front()];const bool hard=best.safety.finiteFailures==0&&best.safety.illegalBounds==0&&best.safety.staleDirection==0&&best.safety.quietResidual==0&&best.safety.stopResidual==0;const bool horizon=best.allHorizon.q(.50)>8.0;const std::string disposition=hard&&horizon?"V2.4-X1 PASS — SOURCE-NATIVE FORECASTABILITY GENERALIZES — READY FOR X2 HOLDOUT QUALIFICATION":"V2.4-X1 PARTIAL — Q3 REMAINS STRONG BUT FORECASTABILITY / HORIZON POLICY REQUIRES FURTHER DEVELOPMENT";std::ostringstream out;out<<"# V2.4-X1 Source-Native Forecastability & Adaptive Horizon\n\n## Final disposition\n\n"<<disposition<<"\n\n1. Production identity: 37b6bf2f7dbd63ea06a9674641ce99cf07191a5f; qualified mathematics: 055e047e2847fc2ec0f59ec457188f66124898e7.\n2. X0 generator/lock: v2.4-X0-source-native-1, manifest "<<kExpectedManifest<<".\n3. All X0 identities were reverified before research; HOLDOUT was never materialized.\n4. Q3 is the unchanged three-point source-report estimator; Q5 is diagnostic only.\n5. The retained mechanism is one causal bounded-risk model and one adaptive horizon, separate from hard safety.\n6. DEVELOPMENT p90 normalizers: innovation "<<number(c.scales.innovation)<<", disagreement "<<number(c.scales.disagreement)<<", curvature "<<number(c.scales.curvature)<<", age/cadence "<<number(c.scales.age)<<".\n7. Selected candidates: ";for(const size_t i:selected)out<<kRiskSpecs[i].name<<' ';out<<".\n8. Best DEVELOPMENT bounded MAE/p95/p99: "<<number(best.allBounded.mean())<<" / "<<number(best.allBounded.q(.95))<<" / "<<number(best.allBounded.q(.99))<<"; median horizon "<<number(best.allHorizon.q(.50))<<" ms.\n9. VALIDATION was replayed exactly once after x1_validation_lock.json; results are in validation CSVs.\n10. HARD correctness for selected DEVELOPMENT candidate: "<<(hard?"PASS":"FAIL")<<".\n11. Oracle rows are NON_CAUSAL_DIAGNOSTIC_ONLY.\n12. Torture remains descriptive safety evidence, not fitness. Physical traces retain LATENT_POSITION_PROXY_ONLY truth semantics.\n13. Production equivalence is inherited only from the sealed exact-commit X0 receipt: 52,463 / 52,463 EXACT; this X1 branch has no production source edits.\n14. X2 boundary: only after independent review of this sealed result may the reserved HOLDOUT be qualified; do not integrate, tune, merge, or release from X1.\n\n"<<disposition<<"\n";return out.str(); }
std::string validatedFinalReport(const Calibration &c,const std::array<Result,4> &development,const std::vector<size_t> &selected,const std::array<Result,3> &validation) { std::string report=finalReport(c,development,selected,validation);const auto &r=validation.front();const bool pass=r.safety.finiteFailures==0&&r.safety.illegalBounds==0&&r.safety.staleDirection==0&&r.safety.quietResidual==0&&r.safety.stopResidual==0&&r.allHorizon.q(.50)>8.0;const std::string wanted=pass?"V2.4-X1 PASS — SOURCE-NATIVE FORECASTABILITY GENERALIZES — READY FOR X2 HOLDOUT QUALIFICATION":"V2.4-X1 PARTIAL — Q3 REMAINS STRONG BUT FORECASTABILITY / HORIZON POLICY REQUIRES FURTHER DEVELOPMENT";const std::array<std::string,2> alternatives{"V2.4-X1 PASS — SOURCE-NATIVE FORECASTABILITY GENERALIZES — READY FOR X2 HOLDOUT QUALIFICATION","V2.4-X1 PARTIAL — Q3 REMAINS STRONG BUT FORECASTABILITY / HORIZON POLICY REQUIRES FURTHER DEVELOPMENT"};for(const auto &old:alternatives)for(size_t at=report.find(old);at!=std::string::npos;at=report.find(old,at+wanted.size()))report.replace(at,old.size(),wanted);const size_t end=report.rfind("\n\n");report.insert(end,"\n15. Frozen VALIDATION bounded MAE/p95/p99: "+number(r.allBounded.mean())+" / "+number(r.allBounded.q(.95))+" / "+number(r.allBounded.q(.99))+"; median horizon "+number(r.allHorizon.q(.50))+" ms; hard correctness "+(pass?"PASS":"FAIL")+".\n");return report; }
