    std::ostringstream candidateRows,pareto,quality,horizon,correlation;candidateRows<<"candidate,quality_budget,development_raw_mae,development_bounded_mae,development_p95,development_p99,median_horizon_ms,hard_correctness\n";pareto<<"candidate,pareto_retained,mae,p99,median_horizon_ms\n";quality<<"candidate,semantic,hard_absolute_limit\n";horizon<<"candidate,median_ms,p10_ms,p25_ms,p75_ms,p90_ms,under_half_source_period,half_to_one,one_to_onehalf,onehalf_to_two,over_two\n";correlation<<"feature,pearson_raw_q3_future_error\n";const std::array<std::string_view,4> fn{"source_innovation","q3_q5_disagreement","curvature_risk","source_age_cadence_risk"};for(size_t i=0;i<4;++i){const auto &r=devResults[i];const bool retained=std::find(selected.begin(),selected.end(),i)!=selected.end();candidateRows<<kRiskSpecs[i].name<<','<<(kRiskSpecs[i].budget==BudgetId::Absolute?"QB-A_ABSOLUTE":kRiskSpecs[i].budget==BudgetId::Travel?"QB-B_POSITION_PLUS_TRAVEL":"QB-C_V23_EQUIVALENT")<<','<<number(r.allRaw.mean())<<','<<number(r.allBounded.mean())<<','<<number(r.allBounded.q(.95))<<','<<number(r.allBounded.q(.99))<<','<<number(r.allHorizon.q(.50))<<','<<(r.safety.finiteFailures+r.safety.illegalBounds+r.safety.staleDirection+r.safety.quietResidual+r.safety.stopResidual==0?"PASS":"FAIL")<<'\n';pareto<<kRiskSpecs[i].name<<','<<(retained?"true":"false")<<','<<number(r.allBounded.mean())<<','<<number(r.allBounded.q(.99))<<','<<number(r.allHorizon.q(.50))<<'\n';quality<<kRiskSpecs[i].name<<','<<(kRiskSpecs[i].budget==BudgetId::Absolute?"QB-A absolute position":kRiskSpecs[i].budget==BudgetId::Travel?"QB-B position plus normalized source travel":"QB-C V2.3-equivalent aggregate target")<<",0.060\n";}for(size_t i=0;i<fn.size();++i)correlation<<fn[i]<<','<<number(devResults[selected.front()].correlations[i].pearson())<<'\n';const auto &best=devResults[selected.front()];horizon<<kRiskSpecs[selected.front()].name<<','<<number(best.allHorizon.q(.50))<<','<<number(best.allHorizon.q(.10))<<','<<number(best.allHorizon.q(.25))<<','<<number(best.allHorizon.q(.75))<<','<<number(best.allHorizon.q(.90))<<",reported_by_family_distribution,reported_by_family_distribution,reported_by_family_distribution,reported_by_family_distribution,reported_by_family_distribution\n";
